/* Контроль, формат, вес оценки и нагрузка для лёгких карточек — ПРИМЕР, считаются из типа предмета и сложности. */
const lxCtrl=(r)=>/практик/i.test(r[0])||/Физическая|Межфакультетские/.test(r[0])?'Зачёт':r[2]==='v'?'Зачёт':'Экзамен';
const lxFmt=(n)=>{const t=n.toLowerCase();return /язык|переписк|речи/.test(t)?['Устно','Письменно']:/практик|физическая|межфак/.test(t)?['Устно']:/статист|данн|информат|учёт|финанс|оценка|налог|инвест|банк|логист/.test(t)?['Письменно','Тест']:/маркет|бренд|менедж|лидер|переговор|конфликт|изменен|дизайн|эджайл|бизнес/.test(t)?['Кейс','Устно']:['Тест','Устно']};
const lxGrade=c=>c==='Экзамен'?[['Работа на семинарах',20],['Проект или контрольная',30],['Экзамен',50]]:[['Посещаемость и активность',30],['Задания в семестре',40],['Зачёт',30]];
const SUBJECTS = [...FULL.map(s=>({...s,full:true})), ...LIGHT.map((r,i)=>{const x=LX[r[0]],c=lxCtrl(r),base={id:'s'+(i+1),name:r[0],courses:r[1],req:r[2],sems:r[3]||undefined,alias:r[4]};if(!x)return {...base,full:false};return {...base,full:true,lite:true,control:c,formats:lxFmt(r[0]),load:3,about:x[0],topics:x[1],grade:lxGrade(c),errors:x[2],tasks:x[3],reviews:[[r[1][0]+' курс',x[4]]]}})]
  .map(s=>({...s,sems:s.sems||s.courses.flatMap(c=>[2*c-1,2*c])}));
SUBJECTS.forEach(s=>{if(s.lite){const d=SUBJ_DIFF_RAW[s.name];s.load=d?Math.max(1,d.lv):3}});

