const sampleHtml=(s,show)=>`<article class="nb ${show?'nb-show':''}" aria-label="Разбор задачи"><div class="nb-sheet"><header class="nb-top"><h3>Разбор задачи</h3>${EX}</header><div class="nb-cols"><div><p class="nb-cond">${s.cond}</p><h4>Что есть что</h4><dl class="nb-vars">${s.vars.map(v=>`<div><dt class="m">${v[0]}</dt><dd><span>${v[1]}</span><b>${v[2]}</b></dd></div>`).join('')}</dl><h4>Формула</h4><div class="nb-f">${s.f}</div></div><div><h4>Решение по действиям</h4><ol class="nb-steps">${s.steps.map((x,i)=>`<li style="--i:${i}"><i class="nb-n">${i+1}</i><div><b>${x[0]}</b><div class="nb-calc">${x[1]}</div></div></li>`).join('')}</ol><div class="nb-ans"><span>Ответ</span><b>${s.ans}</b><i class="nb-stamp" aria-hidden="true">Зачтено</i></div></div></div></div><div class="nb-why">${spr('lat_read',LN)}<p><b>${HELP} объясняет</b>${s.why}</p></div></article>`;
