 if(t==='notes'&&topicsOf(s).length)return notesHtml(s);
 if(!s.full)return latEmpty('Материалы ещё собираем',`${HELP} добавит их после сверки с программой курса.`)+(t==='notes'?earnCard(s):'');
 if(t==='over')return `<section class="card pad"><h2>О чём предмет</h2><p>${s.about}</p><div style="margin-top:6px">${s.topics.map(x=>`<div class="li"><b>${x[0]}</b></div>`).join('')}</div></section><section class="card pad"><div class="hh"><h2>Как оценивают</h2>${EX}</div>${s.grade.map(g=>`<div class="w-r"><div class="top"><span>${g[0]}</span><b>${g[1]}%</b></div><div class="w-b"><i style="width:${g[1]}%"></i></div></div>`).join('')}<button class="link" data-prop="${s.id}" data-i="new" data-type="program">Программа изменилась? Сообщи</button></section><section class="card pad"><h2>Типичные ошибки</h2>${s.errors.map(e=>`<div class="li">${e}</div>`).join('')}</section>`;
 if(t==='notes')return notesHtml(s);
