R.subject=(p,id)=>{const s=byId(id);if(!s)return R.notfound();curS=s;curT=TABS.some(x=>x[0]===p.tab)?p.tab:'over';const k=KIND[kindOf(s)];
 return{title:`${s.name}: конспекты, контрольные, проекты`,after:()=>tabSet(curT),html:`<section class="phero bg-${k[1]}"><div class="wrap"><div><nav class="crumbs" aria-label="Навигация"><a href="/">Главная</a><span aria-hidden="true">/</span><a href="/subjects">Предметы</a></nav><h1 tabindex="-1">${hy(s.name)}</h1><div class="tags"><span class="tag">${cLabel(s)}</span><span class="tag">${sLabel(s)}</span><span class="tag">${s.req==='v'?'По выбору':'Обязательный'}</span>${s.full?`<span class="tag">${s.control}</span>`:''}${diffTag(s)}</div>${diffOf(s)&&diffOf(s).note?`<p class="dnote">${esc(diffOf(s).note)}</p>`:''}<div class="cta">${S.tier?`<button class="btn btn-w cta1" data-tabgo="notes">Открыть конспекты</button>`:mainCta('btn-w')}<button class="btn btn-wo" data-fav="${s.id}">${favLabel(s.id)}</button>${S.admin?`<button class="btn btn-wo" data-diff="${s.id}">Изменить сложность</button>`:''}</div></div>${gcard(s,true)}</div></section>
<div class="tabsbar"><div class="wrap" role="tablist">${TABS.map(x=>`<button class="tab" role="tab" data-tab="${x[0]}" aria-selected="false">${x[2]&&!has(x[2])?I.lock:''}${x[0]==='rev'?revLabel(s):x[1]}</button>`).join('')}</div></div>
<div class="wrap subj"><div class="stack" id="tabC"></div><aside class="side">${s.full?`<div class="card pad latip">${spr('lat_read',LN)}<b>${HELP} советует</b><p class="small muted">${s.errors[0]}. Проверь это первым.</p></div>`:''}<div class="card pad"><b>Отзывы</b><p class="small muted">${revSummary(s)}</p><button class="link" data-tabgo="rev">Читать и написать</button></div><div class="card pad"><b>Групповая работа?</b><p class="small muted">Веди её в трекере проектов.</p><a class="link" href="/projects">Открыть трекер</a></div></aside></div>`}};

