const ava=x=>`<span class="ava">${x.mem.slice(0,4).map(m=>`<i>${esc(m[0][0].toUpperCase())}</i>`).join('')}</span>`;
const meIdx=x=>Math.max(0,x.mem.findIndex(m=>m[0]===ME));
const ownN=()=>S.projects.filter(x=>x.own).length;
const late=t=>t.c<3&&t.e<T0;
const LATE='<span class="tag bad">просрочено</span>';
function addProject(name,subj){if(ownN()>=limit())return null;const x={id:'p'+Date.now(),own:true,name,subj,mem:[[ME,'owner']],tasks:PROJ_TASKS.map((t,i)=>mk(t,0,0,i*5,i*5+6)),notes:[]};S.projects.push(x);save();goal('project_create');return x}
function joinDemo(){if(!pById('brand')){S.projects.push({id:'brand',own:false,name:DEMO_INV.name,subj:'',mem:[[DEMO_INV.from,'owner'],[ME,DEMO_INV.role]],tasks:[mk('Выбрать бренд',3,0,-6,-2),mk('Собрать референсы',1,1,-1,5),mk('Сделать презентацию',0,0,5,12)],notes:[note('Добро пожаловать в проект',DEMO_INV.from)]});save();goal('invite_accept')}}
const pcard=x=>`<article class="card pc"><h3><a href="/project/${x.id}">${esc(x.name)}</a></h3><p class="muted small">${x.subj&&byId(x.subj)?byId(x.subj).name:'Без предмета'}</p><div class="prog" style="margin:0"><i style="width:${pct(x)}%"></i></div><div class="foot"><span class="small muted">Готово ${pct(x)}%</span>${ava(x)}</div><div class="foot"><a class="link" href="/project/${x.id}">Открыть</a><button class="link" data-pdel="${x.id}" style="color:var(--ink-2)">${x.own?'Удалить':'Выйти'}</button></div></article>`;
R.projects=()=>{const title=`Трекер проектов: канбан, диаграмма Ганта, заметки`;
 const l=limit(),n=ownN(),full=has('tracker')&&n>=l,mine=visible().filter(x=>x.own),inv=visible().filter(x=>!x.own);
 const dl=visible().flatMap(x=>x.tasks.filter(t=>t.c<3).map(t=>[x,t])).sort((a,b)=>a[1].e<b[1].e?-1:1).slice(0,5);
 const pendingInv=!pById(DEMO_INV.code);
 const top=!has('tracker')?`<section class="card lock" style="margin-bottom:16px">${spr('ste_rich',SN)}<div><h2>Свои проекты открываются от ${rub(D.access.tracker)}</h2><p>${TAR}: «В проектах, куда тебя пригласили, можно работать бесплатно».</p><a class="btn btn-o btn-sm cta1" href="/pricing">Смотреть тарифы</a></div></section>`:full?`<section class="card lock" style="margin-bottom:16px">${spr('ste_grump',SN)}<div><h2>Лимит ${l} проектов исчерпан</h2><p>${TAR}: «На тарифе «${D.tiers[2].name}» проектов без лимита».</p><a class="btn btn-o btn-sm cta1" href="/pricing">Сменить тариф</a></div></section>`:`<form class="card newp" id="newP"><input type="text" name="n" aria-label="Название проекта" placeholder="Название нового проекта" maxlength="60"><button class="btn btn-o cta1">Создать проект</button></form>`;
 return{title,html:`<div class="wrap"><div class="phead ph-row"><div><h1 tabindex="-1">Трекер проектов</h1><p class="d">${has('tracker')?`Своих проектов: ${l===Infinity?`${n}, без лимита`:`${n} из ${l}`}. `:''}Названия и участники заполнены как ${EX}</p></div>${spr('lat_laptop',LN,'head-cat')}</div>${has('tracker')?top:''}
 ${pendingInv?`<section class="card pad invbar"><div><b>${DEMO_INV.from} приглашает тебя в проект «${DEMO_INV.name}»</b><p class="muted small">Подписка не нужна. Твоя роль: ${ROLES[DEMO_INV.role].toLowerCase()}.</p></div><button class="btn btn-oo btn-sm" data-accept="1">Принять приглашение</button></section>`:''}
 ${dl.length?`<section class="card pad dls"><h2>Ближайшие дедлайны</h2>${dl.map(([x,t])=>`<a class="dl" href="/project/${x.id}"><span><b>${esc(t.t)}</b><small>${esc(x.name)}</small></span><span class="dr">${late(t)?LATE:''}${fmtD(t.e)}</span></a>`).join('')}</section>`:''}
 ${mine.length?`<section class="grp"><h2 class="gh">Мои проекты</h2><div class="pgrid">${mine.map(pcard).join('')}</div></section>`:''}
 ${inv.length?`<section class="grp"><h2 class="gh">Меня пригласили</h2><div class="pgrid">${inv.map(pcard).join('')}</div></section>`:''}${has('tracker')?'':`<div style="margin-top:22px">${top}</div>`}</div>`}};
