const statusLeg=()=>`<ul class="g-leg">${COLS.map((c,i)=>`<li><i class="st${i}"></i>${c}</li>`).join('')}</ul>`;
function ganttHtml(x,ro){
 if(!x.tasks.length)return latEmpty('Задач пока нет','Добавь первую на канбане, и она появится здесь.','lat_sit');
 const ts=[...x.tasks].sort((a,b)=>a.s<b.s?-1:a.s>b.s?1:a.e<b.e?-1:1);
 const a=addD(ts.reduce((m,t)=>t.s<m?t.s:m,ts[0].s),-2),b=addD(ts.reduce((m,t)=>t.e>m?t.e:m,ts[0].e),3),n=dDiff(a,b);
 const P=d=>dDiff(a,d)/n*100;
 const ticks=[];let c=a;for(let i=0;i<=n;i++){if(parseD(c).getDay()===1)ticks.push(c);c=addD(c,1)}
 const todayIn=T0>=a&&T0<=b;
 return `<section class="card pad gantt" data-a="${a}" data-n="${n}">${statusLeg()}<div class="g-body"><div class="g-row g-hd"><div class="g-name"></div><div class="g-track">${ticks.filter(t=>P(t)<93).map(t=>`<span class="tick" style="left:${P(t)}%">${fmtD(t)}</span>`).join('')}</div></div>${todayIn?`<i class="g-today" style="--p:${P(T0)}"><b>сегодня</b></i>`:''}${ts.map(t=>`<div class="g-row"><button class="g-name" data-edit="${t.id}"><b>${esc(t.t)}</b><small>${esc((x.mem[t.a]||x.mem[0])[0])}, ${COLS[t.c].toLowerCase()}, ${fmtD(t.s)} – ${fmtD(t.e)}${t.n?', есть заметка':''}</small>${late(t)?LATE:''}</button><div class="g-track">${ticks.map(k=>`<i class="g-grid" style="left:${P(k)}%"></i>`).join('')}${todayIn?`<i class="g-now" style="left:${P(T0)}%"></i>`:''}<div class="g-bar st${t.c} ${ro?'ro':''}" data-bar="${t.id}" style="left:${P(t.s)}%;width:${Math.max(1.6,(dDiff(t.s,t.e)+1)/n*100)}%" title="${esc(t.t)}: ${fmtD(t.s)} – ${fmtD(t.e)}">${ro?'':'<i class="g-h" data-rs="1"></i>'}</div></div></div>`).join('')}</div><p class="small muted g-tip">${ro?'Наблюдатель видит сроки, но не меняет их.':'Потяни полосу, чтобы сдвинуть сроки, или за правый край, чтобы изменить длину. Нажми на задачу, чтобы открыть её.'}</p></section>`}
function pDraw(){const x=pById(pv.id),box=$('#pv');if(!x||!box)return;const role=(x.mem[pv.as]||x.mem[0])[1],ro=role==='viewer',admin=role==='owner';$$('.tab[data-pv]').forEach(b=>b.setAttribute('aria-selected',b.dataset.pv===pv.view));
 const asU=`<div class="card pad demo-as"><label class="fl" for="asU">Проверить, как видят проект другие</label><select class="f" id="asU">${x.mem.map((m,i)=>`<option value="${i}" ${i===pv.as?'selected':''}>${esc(m[0])}: ${ROLES[m[1]].toLowerCase()}</option>`).join('')}</select></div>`,roNote=ro?'<p class="tag soon ro-n">Наблюдатель только смотрит</p>':'';
 if(pv.view==='board')box.innerHTML=roNote+`<div class="board">${COLS.map((c,ci)=>{const ts=x.tasks.filter(t=>t.c===ci);return `<section class="col" data-col="${ci}"><h3>${c}<span>${ts.length}</span></h3>${ts.map(t=>`<article class="tk ${ro?'ro':''}" draggable="${!ro}" data-t="${t.id}"><button class="tk-t" data-edit="${t.id}">${esc(t.t)}</button>${t.n?`<p class="tk-n">${esc(t.n)}</p>`:''}<div class="m1"><span>${esc((x.mem[t.a]||x.mem[0])[0])}</span><span>${late(t)?LATE:''} ${fmtD(t.e)}</span></div>${ro?'':`<div class="mv"><button data-mv="-1" aria-label="Переместить задачу назад" ${ci?'':'disabled'}>‹</button><button data-mv="1" aria-label="Переместить задачу вперёд" ${ci<3?'':'disabled'}>›</button></div>`}</article>`).join('')}${ci===0&&!ro?`<form class="addt" id="addT"><input type="text" name="t" aria-label="Новая задача" placeholder="Новая задача" maxlength="80"><button aria-label="Добавить задачу">+</button></form>`:''}</section>`}).join('')}</div>`;
 if(pv.view==='gantt')box.innerHTML=roNote+ganttHtml(x,ro);
 if(pv.view==='notes')box.innerHTML=`${ro?'':`<form class="card newp" id="nAdd"><input type="text" name="t" aria-label="Текст заметки" placeholder="Короткая заметка для команды" maxlength="200"><button class="btn btn-oo btn-sm">Добавить заметку</button></form>`}${x.notes.length?`<div class="notes">${x.notes.map((n,i)=>`<article class="note n${i%3}"><textarea data-note="${i}" rows="4" aria-label="Заметка" maxlength="200" ${ro?'readonly':''}>${esc(n.t)}</textarea><footer><span>${esc(n.by)}, ${fmtD(n.at)}</span>${ro?'':`<button class="ib" data-ndel="${i}" aria-label="Удалить заметку">${I.x}</button>`}</footer></article>`).join('')}</div>`:latEmpty('Заметок пока нет',`${HELP} советует записать здесь договорённости команды.`,'lat_read')}`;
 if(pv.view==='people'){const link=`https://${D.brand}/invite/${x.id}`;box.innerHTML=`<section class="card pad"><h2 class="gh" style="margin-bottom:8px">Участники и доступы</h2>${x.mem.map((m,i)=>`<div class="mem"><b>${esc(m[0])}</b>${m[1]==='owner'?`<span class="muted">${ROLES.owner}</span><span></span>`:`<select class="f" data-role="${i}" aria-label="Доступ: ${esc(m[0])}" ${admin?'':'disabled'}><option value="editor" ${m[1]==='editor'?'selected':''}>${ROLES.editor}</option><option value="viewer" ${m[1]==='viewer'?'selected':''}>${ROLES.viewer}</option></select><button class="ib" data-rm="${i}" aria-label="Убрать: ${esc(m[0])}" ${admin&&m[0]!==ME?'':'disabled'}>${I.x}</button>`}</div>`).join('')}${admin?`<form class="inv" id="inv"><input type="text" name="u" aria-label="Telegram участника" placeholder="@username в Telegram"><select class="f" name="r" aria-label="Доступ"><option value="editor">${ROLES.editor}</option><option value="viewer">${ROLES.viewer}</option></select><button class="btn btn-oo btn-sm">Добавить</button></form><p class="small" id="invE" style="color:#A81E1E;margin-top:6px" hidden></p><div class="invl"><div><b>Ссылка-приглашение</b><p class="muted small">Участнику нужна только бесплатная регистрация, подписка не нужна.</p><code>${esc(link)}</code></div><button class="btn btn-oo btn-sm" data-copy="${esc(link)}">Скопировать</button></div>`:'<p class="muted small" style="margin-top:10px">Приглашать людей и менять доступы может только владелец.</p>'}</section>${asU}`}
}
R.project=(p,id)=>{const x=pById(id);if(!x||!visible().includes(x))return R.projects();pv.id=id;pv.view=p.v||'board';pv.as=meIdx(x);const admin=x.mem[pv.as][1]==='owner',cta=admin?`<button class="btn btn-o cta1" data-pv="people" data-goal="invite_open">Пригласить участника</button>`:`<a class="btn btn-o cta1" href="/projects">Все проекты</a>`;return{title:`${x.name}: трекер проектов`,after:pDraw,html:`<div class="wrap"><div class="phead ph-row"><div><nav class="crumbs" aria-label="Навигация"><a href="/projects">Трекер проектов</a></nav><h1 tabindex="-1">${esc(x.name)}</h1></div><div class="m-hide">${cta}</div></div><div class="tags ptabs" role="tablist">${[['board','Канбан'],['gantt','<span class="lg">Диаграмма Ганта</span><span class="sm">Гант</span>'],['notes','Заметки'],['people','Участники']].map(v=>`<button class="tab" role="tab" data-pv="${v[0]}" aria-selected="false">${v[1]}</button>`).join('')}</div><div id="pv"></div><div class="d-hide" style="margin-top:16px">${cta}</div></div>`}};
function openTask(id){const x=pById(pv.id),t=x.tasks.find(k=>k.id==id);if(!t)return;lastF=document.activeElement;const ro=x.mem[pv.as][1]==='viewer',dis=ro?'disabled':'';const ov=document.createElement('div');ov.className='overlay';ov.id='ov';ov.innerHTML=`<div class="dlg" role="dialog" aria-modal="true" aria-labelledby="dlgT"><button class="ib x" id="ovX" aria-label="Закрыть">${I.x}</button><h2 id="dlgT">Задача</h2><form id="tEdit" data-t="${t.id}" class="tform"><label>Название<input type="text" name="t" value="${esc(t.t)}" maxlength="80" ${dis}></label><div class="two2"><label>Статус<select class="f" name="c" ${dis}>${COLS.map((c,i)=>`<option value="${i}" ${i===t.c?'selected':''}>${c}</option>`).join('')}</select></label><label>Исполнитель<select class="f" name="a" ${dis}>${x.mem.map((m,i)=>`<option value="${i}" ${i===t.a?'selected':''}>${esc(m[0])}</option>`).join('')}</select></label><label>Начало<input type="date" name="s" value="${t.s}" ${dis}></label><label>Срок<input type="date" name="e" value="${t.e}" ${dis}></label></div><p class="small" id="tErr" style="color:#A81E1E" hidden></p><label>Заметка<textarea name="n" rows="3" maxlength="200" placeholder="Что важно помнить по этой задаче" ${dis}>${esc(t.n||'')}</textarea></label>${ro?'':`<div class="dlg-b"><button type="button" class="link" id="tDel" style="color:#A81E1E">Удалить задачу</button><button class="btn btn-o btn-sm">Сохранить</button></div>`}</form></div>`;document.body.append(ov);$('input,textarea,button',$('#tEdit')).focus()}
let lastF=null;
function closeOv(){const o=$('#ov');if(o)o.remove()}
function closeTask(){const had=$('#ov');closeOv();if(had&&lastF&&lastF.isConnected)lastF.focus()}
/* Правки конспектов: предложение, модерация, рубли на счёте */
const seedReviews=()=>{const o={};SUBJECTS.filter(x=>x.full&&x.reviews).forEach((su,i)=>{o[su.id]=su.reviews.map((r,j)=>({id:'r'+i+'_'+j,t:r[1],load:su.load,name:r[0],anon:false,ex:true,at:addD(T0,-(3+i+j*2))}))});o.fin.push({id:'ra1',t:'Контрольные лучше решать на время, дома кажется проще, чем оказывается на паре.',load:5,name:'',anon:true,ex:true,at:addD(T0,-1)});return o};
const TYPES={fix:'Ошибка или неточность',program:'Программа изменилась',missing:'Чего-то не хватает'};
const seedProps=()=>[
 {id:1,sid:'acc',topic:1,type:'program',by:'Аня',at:addD(T0,-2),text:'Первоначальная стоимость, линейный способ, отражение в учёте. В новой программе добавлен расчёт по ФСБУ 6/2020.',proof:{file:'программа_бухучёт.pdf',link:''},status:'pending'},
 {id:2,sid:'micro',topic:'new',title:'Внешние эффекты',type:'missing',by:'Максим',at:addD(T0,-1),text:'Положительные и отрицательные внешние эффекты, налог Пигу и теорема Коуза.',proof:null,status:'pending'},
 {id:3,sid:'fin',topic:1,type:'fix',by:'Катя',at:T0,text:'Постоянные платежи в конце и в начале периода, вечная рента и её приведённая стоимость.',proof:null,status:'pending'},
 {id:4,sid:'fin',topic:'new',title:'Эффективная ставка',type:'missing',by:ME,at:addD(T0,-12),text:'Как перевести номинальную ставку в эффективную при разной частоте начисления.',proof:null,status:'ok',amount:150},
 {id:5,sid:'math',topic:0,type:'fix',by:ME,at:addD(T0,-8),text:'Вычисление пределов и раскрытие неопределённостей.',proof:null,status:'no',reason:'Текст совпадает с учебником. Перепиши своими словами.'},
 {id:6,sid:'stat',topic:0,type:'fix',by:'Максим',at:addD(T0,-4),text:'То же исправление, что уже принято.',proof:null,status:'no',reason:'Повтор уже принятой правки. Рубли не начислены, штрафа нет.'},
];
S.props=store.get('props',null)||seedProps();S.edits=store.get('edits',{});S.extra=store.get('extra',{});S.wallet=store.get('wallet',{bal:200,log:[['Новая тема в конспекте «Финансовые рынки и институты»',150,addD(T0,-10)],['Перевод от @anya_demo: за помощь с проектом',50,addD(T0,-3)]]});S.reviews=store.get('reviews',null)||seedReviews();{const sr=seedReviews();Object.keys(sr).forEach(k=>{if(!S.reviews[k])S.reviews[k]=sr[k]})};S.admin=store.get('admin',false);
if(!S.extra.fin&&!store.get('extra',null))S.extra={fin:[['Эффективная ставка','Как перевести номинальную ставку в эффективную при разной частоте начисления.',ME]]};
const saveC=()=>{store.set('props',S.props);store.set('edits',S.edits);store.set('extra',S.extra);store.set('wallet',S.wallet)};
const topicsOf=s=>[...(s.topics||[]),...(S.extra[s.id]||[])];
const edits=(s,i)=>S.edits[s.id+':'+i]||[];
const noteText=(s,i)=>{const e=edits(s,i);return e.length?e[e.length-1].t:topicsOf(s)[i][1]};
function wdiff(a,b){const A=a.split(/\s+/).filter(Boolean),B=b.split(/\s+/).filter(Boolean),n=A.length,m=B.length,L=Array.from({length:n+1},()=>new Array(m+1).fill(0));for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)L[i][j]=A[i]===B[j]?L[i+1][j+1]+1:Math.max(L[i+1][j],L[i][j+1]);let i=0,j=0,o=[];while(i<n||j<m){if(i<n&&j<m&&A[i]===B[j]){o.push(esc(A[i]));i++;j++}else if(j<m&&(i>=n||L[i][j+1]>=L[i+1][j])){o.push(`<ins>${esc(B[j])}</ins>`);j++}else{o.push(`<del>${esc(A[i])}</del>`);i++}}return o.join(' ')}
const maxB=()=>Math.max(...D.bounty.map(b=>b[1]));
const earnCard=s=>`<section class="card pad earn">${spr('lat_read',LN,'earn-cat')}<div><h2>Знаешь этот предмет лучше?</h2><p class="muted">Поправь конспект или добавь новое. После проверки начислим до ${rub(maxB())} на счёт, ими можно оплатить подписку.</p><button class="btn btn-oo btn-sm" data-prop="${s.id}" data-i="new" data-type="missing">Предложить материал</button></div></section>`;
function openProp(sid,i,type){lastF=document.activeElement;const s=byId(sid),ts=topicsOf(s),t=type||'fix';const ov=document.createElement('div');ov.className='overlay';ov.id='ov';const pre=(k)=>k==='new'||!has('notes')?'':noteText(s,+k);ov.innerHTML=`<div class="dlg" role="dialog" aria-modal="true" aria-labelledby="dlgT"><button class="ib x" id="ovX" aria-label="Закрыть">${I.x}</button><h2 id="dlgT">Предложить правку</h2><p class="muted small" style="margin:-6px 0 10px">${esc(s.name)}</p><form id="pForm" data-sid="${s.id}" class="tform"><label>Что случилось<select class="f" name="type">${Object.entries(TYPES).map(e=>`<option value="${e[0]}" ${e[0]===t?'selected':''}>${e[1]}</option>`).join('')}</select></label><label>Тема<select class="f" name="topic">${ts.map((x,k)=>`<option value="${k}" ${String(k)===String(i)?'selected':''}>${esc(x[0])}</option>`).join('')}<option value="new" ${i==='new'||!ts.length?'selected':''}>Новая тема</option></select></label><label id="pTitleW" ${i==='new'||!ts.length?'':'hidden'}>Название новой темы<input type="text" name="title" maxlength="80"></label><label>${has('notes')?'Как должно быть':'Что добавить или исправить'}<textarea name="text" rows="5" maxlength="1200" placeholder="Пиши своими словами">${esc(i==='new'||!ts.length?'':pre(i))}</textarea></label><fieldset class="proof"><legend>Доказательство <span class="opt" id="pReq">${t==='program'?'(обязательно, если программа изменилась)':'(необязательно)'}</span></legend><input type="file" name="file" aria-label="Прикрепить файл"><input type="text" name="link" placeholder="Или ссылка на программу курса" aria-label="Ссылка на доказательство"></fieldset><p class="small muted">За простую доработку начисляем до ${rub(D.bounty[0][1])}, за полноценный вклад и новый конспект вплоть до ${rub(maxB())}.</p><p class="small" id="pErr" style="color:#A81E1E" hidden></p><div class="dlg-b"><span></span><button class="btn btn-o btn-sm">Отправить на проверку</button></div></form></div>`;document.body.append(ov);ov._pre=pre;$('select',ov).focus()}
const statusTag=p=>p.status==='ok'?`<span class="tag live">Принято, +${rub(p.amount)}</span>`:p.status==='no'?`<span class="tag bad">Отклонено</span>`:`<span class="tag soon">На проверке</span>`;
