const fineCard=(f,main)=>{const x=ftype(f.type),st=FSTAT[f.status],act=f.status==='active',can=S.wallet.bal>=f.amount,days=dDiff(f.at,T0)<=D.fines.appealDays;return `<article class="fine ${act?'on':''}"><header><h3>${esc(x[1])}</h3><span class="tag ${st[1]}">${st[0]}</span></header><p>${esc(f.note)}</p><dl class="fine-m"><div><dt>Сумма</dt><dd class="fine-a">${rub(f.amount)}</dd></div><div><dt>Пункт правил</dt><dd><a href="/rules">${x[2]}</a></dd></div><div><dt>Дата</dt><dd>${fmtD(f.at)}</dd></div><div><dt>Доказательство</dt><dd>${f.proof?esc(f.proof):'не приложено'}</dd></div></dl>${f.appeal?`<p class="small"><b>Обжалование:</b> ${esc(f.appeal)}</p>`:''}${f.answer?`<p class="small"><b>Ответ администратора:</b> ${esc(f.answer)}</p>`:''}${act?`<div class="fine-b">${can?`<button class="btn btn-o btn-sm ${main?'cta1':''}" data-fpay="${f.id}">Оплатить со счёта</button>`:`<span class="small fine-no">Не хватает ${rub(f.amount-S.wallet.bal)}. <a href="/contrib">Заработать правками</a></span>`}${days?`<button class="btn btn-oo btn-sm" data-fapp="${f.id}">Обжаловать</button>`:''}</div>`:''}</article>`};
