 if(b=q('[data-fav]')){const id=b.dataset.fav,i=S.fav.indexOf(id);if(i<0)S.fav.push(id);else S.fav.splice(i,1);store.set('fav',S.fav);b.textContent=favLabel(id);toast(i<0?'Добавлено в «Мои предметы»':'Убрано из «Моих предметов»')}
 if(b=q('[data-fl]')){const st=train[curS.id],a=b.dataset.fl;if(a==='show')st.show=true;if(a==='yes'||a==='no'){if(a==='yes')st.ok++;st.i++;st.show=false}if(a==='again'){st.i=0;st.ok=0;st.show=false}tabSet('trainer')}
 if(b=q('[data-pnew]')){const x=addProject(b.dataset.pnew,b.dataset.subj);if(x)LOC.hash='/project/'+x.id;else{toast(`${TAR}: лимит проектов на этом тарифе исчерпан`);LOC.hash='/projects'}}
 if(b=q('[data-pdel]')){if(b.dataset.arm){S.projects=S.projects.filter(x=>x.id!==b.dataset.pdel);save();route()}else{b.dataset.arm=1;b.textContent='Точно?'}}
