const ORIG={};SUBJECTS.forEach(s=>ORIG[s.id]={about:s.about,topics:(s.topics||[]).map(x=>[...x]),tasks:[...(s.tasks||[])]});
function applyCEdit(id){const ids=id?[id]:Object.keys(S.cEdit);ids.forEach(k=>{const s=byId(k),e=S.cEdit[k]||ORIG[k];if(!s||!e)return;s.about=e.about;s.topics=e.topics.map(x=>[...x]);s.tasks=[...e.tasks]})}
