function massSync(){const a=$$('[data-msel]'),n=a.filter(x=>x.checked).length,all=$('#mAll');if($('#mN'))$('#mN').textContent=n?`Выбрано: ${n}`:'Ничего не выбрано';if($('#mOk'))$('#mOk').disabled=$('#mNo').disabled=!n;if(all){all.checked=n===a.length;all.indeterminate=n>0&&n<a.length}}
