const ADM_H='f1aa0e16e109b4f7c892fb32cc53541a9ee74729fe8b005104fc027ff5ae97a2';
S.adminSess=store.get('adminSess',false);
/* Один раз сбрасываем демо-доступ, оставшийся от старой версии с переключателем */
