async function sha256(t){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(t));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
PUBLIC.add('login');
S.accs=store.get('accs',{});S.myLogin=store.get('myLogin','');
const saveAcc=()=>{store.set('accs',S.accs);store.set('myLogin',S.myLogin)};
const syncAcc=()=>{if(S.auth&&!S.adminSess&&S.myLogin&&S.accs[S.myLogin]){S.accs[S.myLogin].tier=S.tier;saveAcc()}};
const LOGIN_RE=/^[a-z0-9_.-]{3,24}$/;
R.login=()=>{if(S.adminSess)return{title:`Администратор: ${D.brand}`,html:`<div class="wrap narrow"><div class="card reg">${spr('lat_read',LN,'reg-cat')}<h1 tabindex="-1" class="h1">Ты вошёл как администратор</h1><p class="muted">Сверху есть переключатель «Доступ»: в нём можно посмотреть сайт глазами гостя или любого тарифа.</p><a class="btn btn-o btn-full cta1" href="/admin">Открыть модерацию</a><button class="btn btn-oo btn-full" id="admOut2" style="margin-top:10px">Выйти</button></div></div>`};
 if(S.auth)return R.account();
 return{title:`Вход: ${D.brand}`,html:`<div class="wrap narrow"><div class="phead"><h1 tabindex="-1">Вход</h1><p class="d">По логину и паролю. Нет аккаунта? <a href="/register">Зарегистрируйся через Telegram</a>, это бесплатно.</p></div><form class="card reg tform" id="admF" novalidate>${spr('lat_wave',LN,'reg-cat')}<label>Логин<input type="text" name="u" autocomplete="username" autocapitalize="off" spellcheck="false" required></label><label>Пароль<input type="password" name="p" autocomplete="current-password" required></label><p class="small" id="admE" role="alert" style="color:#A81E1E" hidden></p><button class="btn btn-o btn-full cta1">Войти</button><p class="small muted">Забыл пароль? Напиши боту <a href="https://t.me/${D.bot}" target="_blank" rel="noopener">@${D.bot}</a> команду /password, он пришлёт новый.</p></form></div>`}};
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='admF')return;e.preventDefault();const u=f.u.value.trim(),pw=f.p.value,er=$('#admE');
 const err=(t,el)=>{er.hidden=false;er.textContent=t;if(el)el.focus()};
 if(!u||!pw)return err('Введи логин и пароль',u?f.p:f.u);
 if(!(window.crypto&&crypto.subtle))return err('Вход работает только по защищённому адресу https://');
 if(await sha256(`${D.brand}|${u}|${pw}`)===ADM_H){S.adminSess=true;store.set('adminSess',true);setDemo('admin');shell();toast('Вход выполнен: режим администратора');LOC.hash='/admin';return}
 const l=u.toLowerCase(),a=S.accs[l];
 if(!a||a.h!==await sha256(`${D.brand}|${l}|${pw}`)){f.p.value='';return err(a?'Неверный пароль':'Такого логина нет. Зарегистрируйся через Telegram',a?f.p:f.u)}
 S.myLogin=l;saveAcc();setDemo(a.tier?String(a.tier):'free');shell();goal('login');toast(`С возвращением, ${l}`);LOC.hash='/account'});
/* Логин и пароль для сайта после регистрации в боте */
const credForm=(edit)=>`<form class="card pad tform cred" id="credF" novalidate><h2>${edit?'Сменить пароль':'Придумай логин и пароль'}</h2><p class="small muted">${edit?`Твой логин: <b>${esc(S.myLogin)}</b>`:'По ним будешь входить на сайт с любого устройства. Регистрация в боте уже есть.'}</p>${edit?'':`<label>Логин<input type="text" name="u" autocomplete="username" autocapitalize="off" spellcheck="false" maxlength="24" placeholder="латиница, цифры, _ . -"></label>`}<label>${edit?'Новый пароль':'Пароль'}<input type="password" name="p" autocomplete="new-password" minlength="6" placeholder="не короче 6 символов"></label><label>Повтори пароль<input type="password" name="p2" autocomplete="new-password"></label><p class="small" id="credE" role="alert" style="color:#A81E1E" hidden></p><button class="btn btn-o btn-sm">${edit?'Сохранить пароль':'Сохранить и войти'}</button></form>`;
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='credF')return;e.preventDefault();const er=$('#credE'),err=(t,el)=>{er.hidden=false;er.textContent=t;el&&el.focus()};
 const edit=!f.u,l=edit?S.myLogin:f.u.value.trim().toLowerCase(),pw=f.p.value;
 if(!edit&&!LOGIN_RE.test(l))return err('Логин: от 3 до 24 символов, латиница, цифры, _ . -',f.u);
 if(!edit&&(S.accs[l]||l==='redeyat'))return err('Такой логин уже занят',f.u);
 if(pw.length<6)return err('Пароль не короче 6 символов',f.p);
 if(pw!==f.p2.value)return err('Пароли не совпадают',f.p2);
 if(!(window.crypto&&crypto.subtle))return err('Работает только по адресу https://');
 S.accs[l]={h:await sha256(`${D.brand}|${l}|${pw}`),tier:S.tier,at:T0};S.myLogin=l;saveAcc();goal(edit?'password_change':'login_created');toast(edit?'Пароль обновлён':`Готово: входи на сайт как ${l}`);rerender()});
const _RT=R.thanks;R.thanks=p=>{const v=_RT(p);if(!S.myLogin)v.html=v.html.replace(/<\/div><\/div>$/,`</div>${credForm(false)}</div>`);return v};
const _RAcc2=R.account;R.account=(...a)=>{const v=_RAcc2(...a);syncAcc();if(S.auth&&!S.adminSess&&v.html.includes('Кабинет'))v.html=v.html.replace(/<\/div>$/,`<section class="sec">${credForm(!!S.myLogin)}</section></div>`);return v};
