/* Пиксель-арт читается, только если каждый пиксель спрайта = целое число экранных пикселей (1x, 2x, 3x) и не меньше 1x.
   Маленькие чиби (до 120px исходника) приводим к ближайшему целому масштабу. */
function pxSnap(){document.querySelectorAll('img.px').forEach(i=>{const go=()=>{if(!i.naturalHeight||i.naturalHeight>120)return;i.style.height='';i.style.width='';i.style.maxWidth='';i.style.maxHeight='';const h=i.getBoundingClientRect().height;if(!h)return;const r=h/i.naturalHeight;let k=Math.max(1,Math.floor(r)+(r%1>=.3?1:0));const box=i.closest('.tc-art');if(box){const bh=box.clientHeight-8,bw=box.clientWidth-8;k=Math.max(1,Math.min(k,Math.floor(bh/i.naturalHeight),Math.floor(bw/i.naturalWidth)))}i.style.height=i.naturalHeight*k+'px';i.style.width=i.naturalWidth*k+'px';i.style.maxWidth='none';i.style.maxHeight='none'};i.complete?go():i.addEventListener('load',go,{once:true})})}
(()=>{let t=0;const run=()=>{cancelAnimationFrame(t);t=requestAnimationFrame(pxSnap)};new MutationObserver(run).observe(document.body,{childList:true,subtree:true});addEventListener('resize',run);addEventListener('load',run)})();

document.addEventListener('click',e=>{if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const a=e.target.closest('a[href]');if(!a||a.target||a.hasAttribute('download'))return;const h=a.getAttribute('href');if(!h.startsWith('/')||h.startsWith('//')||/^\/(img|fonts)\//.test(h)||/\.[a-z0-9]{2,4}$/i.test(h.split('?')[0]))return;e.preventDefault();LOC.hash=h});
